INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"567fc25e-ead5-5205-9faa-39b0c781a1ff","title":"Mathematics · Grade 11 · Term 2: Circle geometry, coordinates and functions","subject":"Mathematics","grade":"Grade 11","questions":[{"question":"The angle at the centre of a circle is 100°. What is the angle at the circumference subtended by the same arc?","options":["50°","100°","200°","80°"],"correct_index":0,"explanation":"The angle at the centre is twice the angle at the circumference on the same arc. Divide 100° by 2."},{"question":"Find the gradient of the line through (1; 2) and (5; 10).","options":["1/2","2","8","4"],"correct_index":1,"explanation":"Gradient = change in y / change in x = (10−2)/(5−1) = 2. Use the same subtraction order in both differences."},{"question":"Where is the turning point of y = (x − 2)² + 3?","options":["(−2; 3)","(2; −3)","(2; 3)","(0; 3)"],"correct_index":2,"explanation":"In y = a(x−p)²+q the turning point is (p; q). The horizontal shift has the opposite sign to the bracket's constant."},{"question":"For y = 3/x + 1, which line is a horizontal asymptote?","options":["x = 1","y = 0","x = 0","y = 1"],"correct_index":3,"explanation":"As the magnitude of x grows, 3/x approaches 0, so y approaches 1. x = 0 is the vertical asymptote."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Circle geometry, coordinates and functions. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","math"],"metadata":{"term":2,"focus":"Circle geometry, coordinates and functions","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=d9piy_Yst2E%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"007cd3e5-65d1-5c92-bebd-94c93d83ded6","title":"Mathematics · Grade 11 · Term 3: Trigonometric rules, probability and finance","subject":"Mathematics","grade":"Grade 11","questions":[{"question":"Two sides of a triangle are 6 cm and 8 cm with included angle 30°. Find its area.","options":["24 cm²","12 cm²","48 cm²","14 cm²"],"correct_index":1,"explanation":"Area = ½ab sin C = ½ × 6 × 8 × ½ = 12 cm². The stated angle must be between the sides used."},{"question":"A triangle has sides 5 and 7 with included angle 60°. Find the square of the opposite side.","options":["74","109","39","25"],"correct_index":2,"explanation":"Cosine rule: c² = 5²+7²−2(5)(7)cos60° = 74−35 = 39. The question asks for c², not c."},{"question":"Events A and B are independent with probabilities 0.4 and 0.5. Find P(A and B).","options":["0.90","0.10","0.45","0.20"],"correct_index":3,"explanation":"For independent events multiply: 0.4 × 0.5 = 0.20. Adding instead would not give the intersection."},{"question":"An asset of R10 000 depreciates by 10% annually on reducing balance. Value after 2 years?","options":["R8 100","R8 000","R9 000","R12 100"],"correct_index":0,"explanation":"Use 10 000(0.9)² = 8 100. In year two the 10% applies to R9 000, not the original value."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Trigonometric rules, probability and finance. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","math"],"metadata":{"term":3,"focus":"Trigonometric rules, probability and finance","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=d9piy_Yst2E%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"c136b2c0-8e26-5b6d-aaf0-32935b348d0c","title":"Mathematics · Grade 11 · Term 4: Patterns and measurement revision","subject":"Mathematics","grade":"Grade 11","questions":[{"question":"Find the nth term of 2, 6, 12, 20, …","options":["2n²","n² + 2","n² + n","4n − 2"],"correct_index":2,"explanation":"The first differences are 4, 6, 8 and second difference is 2, so the quadratic coefficient is 1. Testing n²+n reproduces every term."},{"question":"A cone has radius 3 cm and perpendicular height 4 cm. Find its volume.","options":["36π cm³","16π cm³","9π cm³","12π cm³"],"correct_index":3,"explanation":"V = ⅓πr²h = ⅓π × 9 × 4 = 12π cm³. Slant height is not used for volume."},{"question":"Simplify √50 in surd form.","options":["5√2","25√2","2√5","10√5"],"correct_index":0,"explanation":"Factor 50 as 25×2, so √50 = √25 × √2 = 5√2. Only a perfect-square factor leaves the root."},{"question":"Solve x² − 5x + 6 = 0.","options":["x = −2 or x = −3","x = 2 or x = 3","x = 1 or x = 6","x = 2 only"],"correct_index":1,"explanation":"Factor as (x−2)(x−3)=0. Either factor can be zero, giving two solutions."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Patterns and measurement revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","math"],"metadata":{"term":4,"focus":"Patterns and measurement revision","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=d9piy_Yst2E%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"86539162-89d6-5893-8b56-bc739e19a4d8","title":"Mathematical Literacy · Grade 11 · Term 2: Tax, tariffs and data","subject":"Mathematical Literacy","grade":"Grade 11","questions":[{"question":"For this exercise, VAT is 15%. Find VAT on a price of R200 excluding VAT.","options":["R230","R30","R26.09","R15"],"correct_index":1,"explanation":"VAT = 200×0.15 = R30. Add it for a VAT-inclusive price of R230. Use the rate provided in the question."},{"question":"A map uses 1:50 000. A route measures 6 cm. Find the actual distance.","options":["30 km","0.3 km","3 km","300 km"],"correct_index":2,"explanation":"6×50 000 = 300 000 cm = 3 000 m = 3 km. Convert units only after applying the scale."},{"question":"Find the range of 12, 15, 19, 21, 28.","options":["19","28","12","16"],"correct_index":3,"explanation":"Range = maximum−minimum = 28−12=16. It describes spread, not the central value."},{"question":"A phone plan charges R100 plus R0.50 per minute. What is the total for 120 minutes?","options":["R160","R60","R220","R100"],"correct_index":0,"explanation":"Variable cost = 120×0.50 = R60. Add the R100 fixed charge to get R160."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Tax, tariffs and data. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","matlit"],"metadata":{"term":2,"focus":"Tax, tariffs and data","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=EqZ41-tXhWA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"33da47d2-4456-57e5-a7b6-122da1919314","title":"Mathematical Literacy · Grade 11 · Term 3: Break-even, loans and design drawings","subject":"Mathematical Literacy","grade":"Grade 11","questions":[{"question":"A stall has fixed costs R300, sells items for R20 and spends R5 per item. How many items break even?","options":["15","60","20","12"],"correct_index":2,"explanation":"Each item contributes R20−R5 = R15 towards fixed costs. R300/R15 = 20 items; then total revenue equals total cost."},{"question":"A loan of R2 000 costs R150 interest and R50 in fees. Find the total repayment.","options":["R2 150","R200","R1 800","R2 200"],"correct_index":3,"explanation":"Add principal, interest and fees: 2 000+150+50 = R2 200. Fees also affect borrowing cost."},{"question":"A design drawing uses 1:20. A table is 1.6 m long in real life. Find its drawing length in cm.","options":["8 cm","80 cm","32 cm","0.08 cm"],"correct_index":0,"explanation":"Convert 1.6 m to 160 cm, then divide by 20. A reduced drawing is shorter than the real table."},{"question":"Actual spending is R3 600; the budget was R3 000. By what percentage did spending exceed the budget?","options":["16.67%","20%","60%","120%"],"correct_index":1,"explanation":"The excess is R600. Divide by the original budget: 600/3 000×100 = 20%, not by actual spending."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Break-even, loans and design drawings. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","matlit"],"metadata":{"term":3,"focus":"Break-even, loans and design drawings","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=EqZ41-tXhWA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"d70f4d08-6e80-59e3-b4d6-77bd93d80b94","title":"Mathematical Literacy · Grade 11 · Term 4: Assembly instructions and integrated revision","subject":"Mathematical Literacy","grade":"Grade 11","questions":[{"question":"An assembly diagram says to attach brace B before tightening bolts C. What is the safest interpretation?","options":["Tighten C fully and ignore B","Guess because order never matters","Use extra parts instead","Fit B first, then tighten C as instructed"],"correct_index":3,"explanation":"The sequence affects fit and stability. Read the full diagram, identify the parts, then follow the specified order."},{"question":"A box is 30 cm × 20 cm × 10 cm. Find its capacity in litres.","options":["6 L","60 L","600 L","0.6 L"],"correct_index":0,"explanation":"Volume = 6 000 cm³. Since 1 000 cm³ = 1 L, capacity is 6 L."},{"question":"A shop offers 20% off R450. What do you pay?","options":["R90","R360","R430","R540"],"correct_index":1,"explanation":"Discount = 0.20×450 = R90. Subtract R90 from R450 to get R360; R90 is the saving."},{"question":"Two fair coin tosses have outcomes HH, HT, TH, TT. P(exactly one head) = ?","options":["1/4","3/4","1/2","1"],"correct_index":2,"explanation":"HT and TH are two of four equally likely outcomes. The word exactly excludes HH."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Assembly instructions and integrated revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","matlit"],"metadata":{"term":4,"focus":"Assembly instructions and integrated revision","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=EqZ41-tXhWA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"a9af42db-f428-58d2-8859-44bf15ca09e1","title":"Physical Sciences · Grade 11 · Term 2: Electricity and intermolecular forces","subject":"Physical Sciences","grade":"Grade 11","questions":[{"question":"A 6 Ω resistor carries 2 A. Find the potential difference across it.","options":["3 V","8 V","12 V","0.33 V"],"correct_index":2,"explanation":"Ohm's law gives V=IR=2×6=12 V for an ohmic resistor under constant physical conditions."},{"question":"A device operates at 12 V and 3 A. Find its electrical power.","options":["4 W","15 W","9 W","36 W"],"correct_index":3,"explanation":"P=VI=12×3=36 W. Power is the rate of energy transfer, measured in watts."},{"question":"Which intermolecular force is especially important between water molecules?","options":["Hydrogen bonding","Metallic bonding","Ionic bonding between whole water molecules","Covalent bonding between separate water molecules"],"correct_index":0,"explanation":"Water has H bonded to O and oxygen lone pairs, enabling hydrogen bonds between molecules. O–H covalent bonds are within each molecule."},{"question":"A coil experiences a larger rate of change of magnetic flux. What happens to the magnitude of induced emf, all else equal?","options":["It necessarily becomes zero","It increases","It decreases to half","It depends only on the coil's colour"],"correct_index":1,"explanation":"Faraday's law relates induced emf magnitude to the rate of change of flux linkage. Faster change gives a larger emf for the same coil."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Electricity and intermolecular forces. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","phsc"],"metadata":{"term":2,"focus":"Electricity and intermolecular forces","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lm60Fp2hw9Y%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"37aabd15-25f2-5cd0-a558-71e5e349d0d3","title":"Physical Sciences · Grade 11 · Term 3: Stoichiometry, gases and energy change","subject":"Physical Sciences","grade":"Grade 11","questions":[{"question":"A sample has mass 8 g and molar mass 16 g·mol⁻¹. Find its amount of substance.","options":["2 mol","128 mol","24 mol","0.5 mol"],"correct_index":3,"explanation":"n=m/M=8/16=0.5 mol. Dividing by molar mass cancels grams and leaves moles."},{"question":"For 2H₂ + O₂ → 2H₂O, how many moles of O₂ react with 6 mol H₂, with enough O₂ available?","options":["3 mol","6 mol","12 mol","2 mol"],"correct_index":0,"explanation":"The mole ratio H₂:O₂ is 2:1, so 6 mol H₂ needs 6/2=3 mol O₂. Coefficients describe mole ratios, not gram ratios."},{"question":"A fixed amount of gas occupies 4 L at 100 kPa. At constant temperature, find its volume at 200 kPa.","options":["8 L","2 L","4 L","0.5 L"],"correct_index":1,"explanation":"Boyle's law: P₁V₁=P₂V₂. V₂=100×4/200=2 L. Doubling pressure halves volume at constant temperature."},{"question":"In an exothermic reaction, how does the enthalpy of products compare with reactants?","options":["It is higher, so ΔH is positive","It must be exactly equal","It is lower, so ΔH is negative","It cannot be compared"],"correct_index":2,"explanation":"Energy is released to surroundings. ΔH=H(products)−H(reactants) is negative because products have lower enthalpy."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Stoichiometry, gases and energy change. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","phsc"],"metadata":{"term":3,"focus":"Stoichiometry, gases and energy change","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lm60Fp2hw9Y%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"83f2241c-c11c-5102-b00c-6f408ab8d4dd","title":"Physical Sciences · Grade 11 · Term 4: Acid–base and redox reactions","subject":"Physical Sciences","grade":"Grade 11","questions":[{"question":"In the Brønsted–Lowry model, an acid is a…","options":["Proton donor","Proton acceptor","Neutron donor","Substance that always contains oxygen"],"correct_index":0,"explanation":"A Brønsted–Lowry acid donates H⁺. A base accepts H⁺, so identify the proton transfer in the reaction."},{"question":"For Zn → Zn²⁺ + 2e⁻, what happens to zinc?","options":["It is reduced by losing electrons","It is oxidised by losing electrons","It gains two electrons","Its oxidation number decreases"],"correct_index":1,"explanation":"Oxidation is loss of electrons. Zinc's oxidation number rises from 0 to +2."},{"question":"Which equation shows neutralisation of HCl by NaOH?","options":["HCl + NaOH → H₂ + NaClO","HCl + NaOH → Na + Cl + O₂","HCl + NaOH → NaCl + H₂O","HCl + NaOH → NaCl only"],"correct_index":2,"explanation":"The acid and base produce salt and water. Check that hydrogen and oxygen atoms are conserved as well as sodium and chlorine."},{"question":"A solution contains 0.2 mol solute in 0.5 dm³. Find its concentration.","options":["0.1 mol·dm⁻³","2.5 mol·dm⁻³","0.7 mol·dm⁻³","0.4 mol·dm⁻³"],"correct_index":3,"explanation":"c=n/V=0.2/0.5=0.4 mol·dm⁻³. Use volume in dm³, not an unconverted millilitre value."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Acid–base and redox reactions. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","phsc"],"metadata":{"term":4,"focus":"Acid–base and redox reactions","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lm60Fp2hw9Y%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"2646f0b2-93c0-5c2a-86ca-98b31592e33d","title":"Life Sciences · Grade 11 · Term 2: Photosynthesis, respiration and nutrition","subject":"Life Sciences","grade":"Grade 11","questions":[{"question":"Which gas is taken in as a raw material for photosynthesis?","options":["Oxygen","Nitrogen only","Hydrogen","Carbon dioxide"],"correct_index":3,"explanation":"Photosynthesis uses carbon dioxide and water to produce organic compounds using light energy. Oxygen is released as a by-product."},{"question":"Why does increasing light eventually stop increasing photosynthesis rate in a healthy plant?","options":["Another factor, such as CO₂ or temperature, becomes limiting","Light ceases to contain energy","The plant stops needing glucose permanently","Water is no longer needed"],"correct_index":0,"explanation":"Once light is no longer limiting, another required factor limits the rate. Experiments should keep other conditions controlled."},{"question":"What is the main purpose of cellular respiration?","options":["To create sunlight","To transfer energy from organic molecules into ATP","To absorb food without enzymes","To remove every oxygen atom from the body"],"correct_index":1,"explanation":"Respiration releases energy through reactions and captures some in ATP, which powers cellular processes. It is not the same as breathing."},{"question":"Where does most absorption of digested nutrients occur in humans?","options":["Oesophagus","Large intestine only","Small intestine","Stomach only"],"correct_index":2,"explanation":"The small intestine has villi and microvilli that increase surface area for absorption of digested nutrients."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Photosynthesis, respiration and nutrition. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","lisc"],"metadata":{"term":2,"focus":"Photosynthesis, respiration and nutrition","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=bj82jNMC2qg%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"92e835f9-aa9e-5d28-82d7-7db4eb99e445","title":"Life Sciences · Grade 11 · Term 3: Gas exchange, excretion and populations","subject":"Life Sciences","grade":"Grade 11","questions":[{"question":"Why are alveolar walls thin and moist?","options":["To support rapid diffusion of gases","To prevent all gas movement","To produce urine","To store solid food"],"correct_index":0,"explanation":"A thin surface shortens diffusion distance; moisture allows gases to dissolve before diffusing across the exchange surface."},{"question":"Which organ removes urea from the blood and helps regulate water balance?","options":["Stomach","Kidney","Heart","Pancreas only"],"correct_index":1,"explanation":"Kidneys filter blood and form urine, removing nitrogenous wastes and regulating water and salts. The liver produces urea from excess amino nitrogen."},{"question":"What happens when ADH secretion increases in a healthy person?","options":["Less water is reabsorbed and all urine stops","Blood sugar always doubles","More water is reabsorbed, usually producing a smaller volume of more concentrated urine","No kidney response is possible"],"correct_index":2,"explanation":"ADH increases water reabsorption in the kidney, generally reducing urine volume and making it more concentrated. Distinguish urine volume from concentration."},{"question":"A population gains 30 births and 10 immigrants, with 20 deaths and 5 emigrants. Find its net change.","options":["Increase of 45","Decrease of 15","Increase of 65","Increase of 15"],"correct_index":3,"explanation":"Change = births+immigration−deaths−emigration = 30+10−20−5 = +15 individuals."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Gas exchange, excretion and populations. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","lisc"],"metadata":{"term":3,"focus":"Gas exchange, excretion and populations","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=bj82jNMC2qg%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"86b1a333-88c1-5567-bcce-141f843e1737","title":"Life Sciences · Grade 11 · Term 4: Human impact and environmental evidence","subject":"Life Sciences","grade":"Grade 11","questions":[{"question":"How can excess fertiliser entering a dam harm aquatic life?","options":["It permanently increases oxygen in all depths","It can cause algal growth and oxygen depletion during decomposition","It stops all biological activity immediately","It turns fresh water directly into salt water"],"correct_index":1,"explanation":"Nutrient enrichment can cause eutrophication. Decomposers use dissolved oxygen as excess organic material breaks down, threatening aquatic organisms."},{"question":"Why does destroying wetlands threaten water quality?","options":["Wetlands have no role in water movement","Wetlands create all pollutants","Wetlands can trap sediments and help filter pollutants","Wetlands prevent every flood regardless of size"],"correct_index":2,"explanation":"Wetlands provide important filtration and flow-regulation services. Their protection reduces risks, although it cannot eliminate all pollution or flooding."},{"question":"Which action most directly lowers a school's electricity-related carbon footprint when electricity comes from fossil fuels?","options":["Leave empty classrooms fully lit","Burn litter behind the classroom","Replace every indigenous tree with concrete","Reduce unnecessary electricity consumption"],"correct_index":3,"explanation":"Using less fossil-fuel-generated electricity reduces associated emissions. Measure energy use to assess whether the intervention works."},{"question":"A study links habitat fragmentation to falling species numbers. What strengthens its conclusion?","options":["Compare repeated data from fragmented and less-fragmented sites while considering other causes","Use only a single photograph","Ignore differences in sampling effort","Assume correlation proves the only cause"],"correct_index":0,"explanation":"Repeated comparable observations and consideration of confounding factors support stronger evidence. A single correlation is not proof of sole causation."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Human impact and environmental evidence. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","lisc"],"metadata":{"term":4,"focus":"Human impact and environmental evidence","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=bj82jNMC2qg%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"87be3bbb-d6b4-5f83-92c6-9c915ea77a71","title":"Accounting · Grade 11 · Term 2: Partnership statements and analysis","subject":"Accounting","grade":"Grade 11","questions":[{"question":"A partnership earns R90 000 before appropriations. Partner salaries total R30 000; no other appropriations apply. Find residual profit.","options":["R60 000","R120 000","R30 000","R90 000"],"correct_index":0,"explanation":"Residual profit = profit available−partner salaries−other appropriations. Here 90 000−30 000=R60 000, shared using the agreed ratio."},{"question":"Residual profit of R60 000 is shared A:B = 2:1. What is B's share?","options":["R40 000","R20 000","R30 000","R60 000"],"correct_index":1,"explanation":"The ratio has three parts. B receives one part: 60 000/3 = R20 000. Do not divide by B's ratio number alone."},{"question":"A business has current assets R120 000 including stock R40 000, and current liabilities R50 000. Find the acid-test ratio.","options":["2.4:1","0.8:1","1.6:1","3.2:1"],"correct_index":2,"explanation":"Acid-test ratio = (current assets−inventory)/current liabilities = (120 000−40 000)/50 000 = 1.6:1."},{"question":"Why compare a partnership's financial indicators with prior years?","options":["To prove future profit is guaranteed","To avoid reading the financial statements","To ignore different business conditions","To identify trends and investigate performance changes"],"correct_index":3,"explanation":"Comparisons help interpret performance, but context such as changing prices, policies and business conditions still matters."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Partnership statements and analysis. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","acc"],"metadata":{"term":2,"focus":"Partnership statements and analysis","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=qxPOjU7FXcA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"12c679fe-0bd6-5ee2-bfa4-169f11be60ee","title":"Accounting · Grade 11 · Term 3: Budgets, inventory and manufacturing","subject":"Accounting","grade":"Grade 11","questions":[{"question":"A cash sale of R500 occurs in March. Where does it appear in the cash budget?","options":["April receipts automatically","March receipts","March payments","Nowhere because sales are not cash"],"correct_index":1,"explanation":"A cash budget records the timing of actual cash movements. A cash sale is received in March; credit collections need a collection schedule."},{"question":"A business expects 60% of credit sales of R20 000 to be collected next month. Find that collection.","options":["R8 000","R20 000","R12 000","R32 000"],"correct_index":2,"explanation":"Multiply credit sales by the collection proportion: 20 000×0.60=R12 000. The rest is collected later or subject to other assumptions."},{"question":"Fixed costs are R30 000; selling price is R50 per unit and variable cost R20. Find break-even units.","options":["600","1 500","10 000","1 000"],"correct_index":3,"explanation":"Contribution per unit = 50−20=R30. Break-even = fixed costs/contribution = 30 000/30 = 1 000 units."},{"question":"Which statement distinguishes perpetual from periodic inventory?","options":["Perpetual records continuously update stock and cost of sales; periodic calculates cost of sales at intervals","Periodic means stock is never counted","Perpetual means stock cannot be stolen","Both systems forbid stocktaking"],"correct_index":0,"explanation":"The systems differ in recording timing. Physical stocktaking remains useful for verifying balances and identifying losses."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Budgets, inventory and manufacturing. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","acc"],"metadata":{"term":3,"focus":"Budgets, inventory and manufacturing","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=qxPOjU7FXcA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"55063958-fd0c-52ba-8f98-ff06377d6c13","title":"Accounting · Grade 11 · Term 4: VAT and accounting revision","subject":"Accounting","grade":"Grade 11","questions":[{"question":"For this exercise VAT is 15%. A cash sale of R1 000 excluding VAT creates output VAT of…","options":["R1 150","R130.43","R150","R15"],"correct_index":2,"explanation":"Output VAT is charged on taxable sales: 1 000×0.15=R150. The VAT-inclusive receipt is R1 150."},{"question":"Output VAT is R9 000 and deductible input VAT R6 500. Find the net VAT payable.","options":["R15 500","R6 500","R9 000","R2 500"],"correct_index":3,"explanation":"Net VAT payable = output−deductible input = R2 500. If deductible input exceeded output, the position would instead be receivable, subject to rules."},{"question":"For this exercise VAT is 15%. Extract VAT from a VAT-inclusive amount of R230.","options":["R30","R34.50","R200","R15"],"correct_index":0,"explanation":"VAT = inclusive amount×15/115 = 230×15/115 = R30. Taking 15% of the inclusive total uses the wrong base."},{"question":"Why keep a valid tax invoice for a purchase?","options":["It guarantees every expense is deductible","It supports the accounting record and any qualifying input-VAT claim","It replaces the need to pay the supplier","It allows any invented VAT claim"],"correct_index":1,"explanation":"Reliable documentation supports verification. Input VAT is subject to qualifying rules, so an invoice alone does not make every purchase claimable."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: VAT and accounting revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","acc"],"metadata":{"term":4,"focus":"VAT and accounting revision","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=qxPOjU7FXcA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}}]$smartbridge$::jsonb)
